 "content": "def transform(grid):
    """Shear the colored figure leftward by its height, with the bottom row fixed."""
    h, w = len(grid), len(grid[0])
    occupied_rows = [r for r, row in enumerate(grid) if any(v != 0 for v in row)]
    if not occupied_rows:
        return [row[:] for row in grid]
    top, bottom = min(occupied_rows), max(occupied_rows)
    height = bottom - top + 1
    out = [[0] * w for _ in range(h)]
    for r, row in enumerate(grid):
        shift = (r - top) - (height - 1)
        for c, value in enumerate(row):
            nc = c + shift
            if value != 0 and 0 <= nc < w:
                out[r][nc] = value
    return out
